INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00009000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 9), 'unit9-lesson1', 'May for Possibility', '''May'' is used to express possibility. It suggests something is possible but not certain. The structure is Subject + may + V1.', '{"details":[{"concept":"Possibility","explanation":"''May'' is used when something is possible but not certain.","example":"He may be at home.","burmese":"သူ အိမ်မှာ ရှိနိုင်တယ်။"},{"concept":"Possibility (Weather)","explanation":"''May'' is used for possible future events like weather.","example":"It may rain tomorrow.","burmese":"မနက်ဖန် မိုးရွာနိုင်တယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00009001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 9), 'unit9-lesson2', 'May for Permission', '''May'' is used to express permission. ''May not'' is used to deny permission. This is a formal way to ask for or give permission.', '{"details":[{"concept":"Asking Permission","explanation":"''May'' is used to politely ask for permission.","example":"May I come in, Sir? Yes, you may.","burmese":"ဆရာ၊ ဝင်လို့ ရမလား။ ရတယ်၊ ဝင်လို့ရတယ်။"},{"concept":"Denying Permission","explanation":"''May not'' is used to deny permission.","example":"May I go home now? No, you may not.","burmese":"အခု အိမ်ပြန်လို့ ရမလား။ မရဘူး၊ ပြန်လို့ မရဘူး။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00009002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 9), 'unit9-lesson3', 'May for Wishes', '''May'' is used to express wishes or hopes. This is often used in formal or literary expressions.', '{"details":[{"concept":"Blessing","explanation":"''May'' is used to express blessings and good wishes.","example":"May God bless you!","burmese":"ဘုရားသခင် ကောင်းကြီးပေးပါစေ!"},{"concept":"Peace Wish","explanation":"''May'' is used to wish peace for someone.","example":"May his soul rest in peace!","burmese":"သူ့ဝိညာဉ် ငြိမ်းချမ်းစွာ ရောက်ရှိပါစေ!"},{"concept":"Contribution Wish","explanation":"''May'' is used to wish success in contributing.","example":"May you contribute the community!","burmese":"လူမှုအသိုင်းအဝိုင်းအတွက် ပါဝင်ကူညီနိုင်ပါစေ!"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00009003-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 9), 'unit9-lesson4', 'Might as Past Tense of May (Reported Speech)', '''Might'' is the past tense of ''may'' in indirect or reported speech. When we report what someone said, ''may'' changes to ''might''.', '{"details":[{"concept":"Reported Speech","explanation":"In reported speech, ''may'' changes to ''might''.","example":"He said, \\"I may go to school.\\" → He said that he might go to school.","burmese":"သူက \\"ငါကျောင်းသွားနိုင်တယ်\\" လို့ပြောခဲ့တယ်။ → သူက ကျောင်းသွားနိုင်တယ်လို့ ပြောခဲ့တယ်။"},{"concept":"Reported Speech (Writing)","explanation":"The same rule applies for writing activities.","example":"John said, \\"I may write a letter.\\" → John said that he might write a letter.","burmese":"ဂျွန်က \\"ငါစာရေးနိုင်တယ်\\" လို့ပြောခဲ့တယ်။ → ဂျွန်က စာရေးနိုင်တယ်လို့ ပြောခဲ့တယ်။"}]}'::jsonb, 4) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00009004-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 9), 'unit9-lesson5', 'Might for Less Possibility', '''Might'' shows less possibility than ''may''. May suggests about 50% possibility, while might suggests about 30% possibility.', '{"details":[{"concept":"Higher Possibility (May)","explanation":"''May'' suggests a higher chance of something happening (about 50%).","example":"It may rain. (Maybe a 50% possibility)","burmese":"မိုးရွာနိုင်တယ်။ (ဖြစ်နိုင်ခြေ ရာခိုင်နှုန်း ၅၀ ရှိတယ်)"},{"concept":"Lower Possibility (Might)","explanation":"''Might'' suggests a lower chance of something happening (about 30%).","example":"It might rain. (Maybe a 30% possibility)","burmese":"မိုးရွာနိုင်တယ်။ (ဖြစ်နိုင်ခြေ ရာခိုင်နှုန်း ၃၀ ရှိတယ်)"}]}'::jsonb, 5) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00009000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 9), 'unit9-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":901,"question":"________ I go out?","options":["May","Might","Can"],"answer":"May","explanation":"''May'' is used to ask for permission politely. ''Might'' is more formal and less common for permission. ''Can'' is informal. ''May'' ကို ယဉ်ကျေးစွာ ခွင့်ပြုချက်တောင်းရာမှာ သုံးပါ။","points":1},{"id":902,"question":"________ you be free from dangers!","options":["May","Might","Must"],"answer":"May","explanation":"''May'' is used to express wishes or blessings. ''Might'' shows less certainty. ''Must'' is for obligation — not for wishes. ''May'' ကို ဆုတောင်းချက်တွေမှာ သုံးပါ။","points":1},{"id":903,"question":"Sue said that she ________ go to university the day before.","options":["may","might","must"],"answer":"might","explanation":"In reported speech, ''may'' changes to ''might''. ''Sue said'' indicates reported speech. ''Must'' is for obligation. ''Reported speech မှာ ''may'' က ''might'' ပြောင်းပါ။","points":1},{"id":904,"question":"________ I borrow a pen, please?","options":["May","Might","Must"],"answer":"May","explanation":"''May'' is used to politely ask for permission. ''Might'' is very formal. ''Must'' is for obligation — not for asking permission. ''May'' ကို ယဉ်ကျေးစွာ ခွင့်ပြုချက်တောင်းရာမှာ သုံးပါ။","points":1},{"id":905,"question":"It ________ rain later on, but I don''t think it will.","options":["may","might","must"],"answer":"might","explanation":"''Might'' shows less possibility than ''may''. Since the speaker doesn''t think it will rain, ''might'' (lower possibility) is more appropriate. ''I don''t think it will'' ဆိုတာ ဖြစ်နိုင်ခြေနည်းတာကြောင့် ''might'' ကိုသုံးပါ။","points":1},{"id":906,"question":"It ________ rain later on. We''d better take an umbrella.","options":["may","might","must"],"answer":"may","explanation":"''May'' shows higher possibility than ''might''. Since they are preparing for rain, ''may'' (higher possibility) is more appropriate. ''We''d better take an umbrella'' ဆိုတာ ဖြစ်နိုင်ခြေများတာကြောင့် ''may'' ကိုသုံးပါ။","points":1},{"id":907,"question":"She said she ________ take more pictures.","options":["may","might","must"],"answer":"might","explanation":"In reported speech, ''may'' changes to ''might''. ''She said'' indicates reported speech. ''Must'' is for obligation. ''Reported speech မှာ ''may'' က ''might'' ပြောင်းပါ။","points":1},{"id":908,"question":"________ I use your glue just for a moment?","options":["May","Might","Must"],"answer":"May","explanation":"''May'' is used to politely ask for permission. ''Might'' is very formal. ''Must'' is for obligation — not for asking permission. ''May'' ကို ယဉ်ကျေးစွာ ခွင့်ပြုချက်တောင်းရာမှာ သုံးပါ။","points":1},{"id":909,"question":"You ________ come at eleven if you wish.","options":["may","might","must"],"answer":"may","explanation":"''May'' is used to give permission. The speaker is allowing the person to come. ''Might'' is for possibility. ''Must'' is for obligation. ''May'' ကို ခွင့်ပြုချက်ပေးရာမှာ သုံးပါ။","points":1},{"id":910,"question":"Students ________ wear jeans.","options":["mayn''t","mightn''t","mustn''t"],"answer":"mayn''t","explanation":"''Mayn''t'' is used to deny permission formally. ''Mightn''t'' is not standard for prohibition. ''Mustn''t'' is for strong prohibition. For school dress codes, ''mayn''t'' is the formal choice. ''mayn''t'' ကို ခွင့်ပြုချက်ငြင်းဆိုရာမှာ သုံးပါ။","points":1},{"id":911,"question":"He asked if he ________ borrow the car.","options":["may","might","must"],"answer":"might","explanation":"In reported speech (indirect questions), ''may'' changes to ''might''. ''He asked if'' indicates reported speech. ''Must'' is for obligation. ''Reported speech မှာ ''may'' က ''might'' ပြောင်းပါ။","points":1},{"id":912,"question":"They wanted to know if they ________ come later.","options":["may","might","must"],"answer":"might","explanation":"In reported speech, ''may'' changes to ''might''. ''They wanted to know if'' indicates reported speech. ''Must'' is for obligation. ''Reported speech မှာ ''may'' က ''might'' ပြောင်းပါ။","points":1},{"id":913,"question":"I am not sure but I think my camera ________ be broken.","options":["may","might","must"],"answer":"may","explanation":"''May'' is used for possibility. The speaker is unsure, so ''may'' (possibility) is appropriate. ''Might'' shows less possibility. ''Must'' is for obligation. ''May'' ကို ဖြစ်နိုင်ခြေရှိတဲ့အခါ သုံးပါ။","points":1},{"id":914,"question":"I don''t know where your gloves are. They ________ be in the kitchen.","options":["may","might","must"],"answer":"may","explanation":"''May'' is used for possibility. The speaker doesn''t know, so ''may'' (possibility) is appropriate. ''Might'' shows less possibility. ''Must'' is for obligation. ''May'' ကို ဖြစ်နိုင်ခြေရှိတဲ့အခါ သုံးပါ။","points":1},{"id":915,"question":"________ the odds be ever in your favour!","options":["May","Might","Must"],"answer":"May","explanation":"''May'' is used to express wishes or hopes in formal expressions. ''Might'' shows less certainty. ''Must'' is for obligation — not for wishes. ''May'' ကို ဆုတောင်းချက်တွေမှာ သုံးပါ။","points":1},{"id":916,"question":"________ the Force be with you!","options":["May","Might","Must"],"answer":"May","explanation":"''May'' is used to express wishes or blessings. ''Might'' shows less certainty. ''Must'' is for obligation — not for wishes. ''May'' ကို ဆုတောင်းချက်တွေမှာ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

