INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00010000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 10), 'unit10-lesson1', 'Must for Strong Obligation', '''Must'' is used for strong personal obligations. It expresses something that is necessary or very important. The structure is Subject + must + V1.', '{"details":[{"concept":"Personal Obligation","explanation":"''Must'' is used for obligations that come from yourself or are very important.","example":"I must lose some weight.","burmese":"ငါ ဝိတ်ချရမယ်။"},{"concept":"Duty Obligation","explanation":"''Must'' is used for duties and responsibilities.","example":"I must write a letter to John.","burmese":"ငါ ဂျွန်ဆီ စာတစ်စောင် ရေးရမယ်။"},{"concept":"Important Rule","explanation":"''Must'' is used for important rules that must be followed.","example":"Bicyclists must remember to signal when they turn.","burmese":"စက်ဘီးစီးသူများ လှည့်တဲ့အခါ အမှတ်ပေးဖို့ မှတ်ထားရမယ်။"},{"concept":"Exam Obligation","explanation":"''Must'' is used for obligations related to exams and studies.","example":"He must study harder if he wants to pass the exam.","burmese":"သူ စာမေးပွဲ အောင်ချင်ရင် ပိုပြီး ကြိုးစားရမယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00010001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 10), 'unit10-lesson2', 'Mustn''t for Prohibition', '''Mustn''t'' (must not) is used to express that something is prohibited or not allowed. The structure is Subject + mustn''t + V1.', '{"details":[{"concept":"Transport Prohibition","explanation":"''Mustn''t'' is used for rules about transport safety.","example":"Passengers mustn''t talk to the driver.","burmese":"ခရီးသည်များ ဒီရင်ဘောက် စကားမပြောခင်းမရပါ။"},{"concept":"Workplace Prohibition","explanation":"''Mustn''t'' is used for workplace rules.","example":"Policemen mustn''t drink on duty.","burmese":"ရဲတပ်ဖွဲ့ဝင်များ တာဝန်ထမ်းဆောင်နေချိန်မှာ အရက်မသောက်ရပါ။"},{"concept":"Children Prohibition","explanation":"''Mustn''t'' is used for rules about children.","example":"Children mustn''t eat chewing gum.","burmese":"ကလေးများ ဝါဂွမ်းမစားရပါ။"},{"concept":"Classroom Prohibition","explanation":"''Mustn''t'' is used for classroom rules.","example":"They mustn''t use their mobile phones during lessons.","burmese":"သူတို့ သင်ခန်းစာချိန်မှာ မိုဘိုင်းဖုန်းများ အသုံးမပြုရပါ။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00010002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 10), 'unit10-lesson3', 'Must in Questions', '''Must'' can be used in questions to ask about obligation. The structure is Must + subject + V1?', '{"details":[{"concept":"Asking About Obligation","explanation":"''Must'' is used to ask if something is required.","example":"Must I go to the party?","burmese":"ကျွန်တော် ပါတီသွားရမလား။"},{"concept":"Asking About Necessity","explanation":"''Must'' is used to ask about the necessity of an action.","example":"Must he make so much noise?","burmese":"သူ ဆူညံစွာ လုပ်ရမလား။"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00010003-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 10), 'unit10-lesson4', 'Important Notes About Must', '''Must'' is used only in the present and future. The past form of ''must'' is ''had to''. ''Must'' does not exist in the past tense.', '{"details":[{"concept":"Present and Future Only","explanation":"''Must'' can only be used for present and future obligations.","example":"I must finish this work before I leave.","burmese":"ငါ ထွက်ခင် ဒီအလုပ်ကို ပြီးအောင်လုပ်ရမယ်။"},{"concept":"Past Form is Had To","explanation":"For past obligations, use ''had to'' instead of ''must''.","example":"I had to finish the work yesterday. (Not: I musted finish)","burmese":"ငါ မနေ့က ဒီအလုပ်ကို ပြီးအောင်လုပ်ရတယ်။"}]}'::jsonb, 4) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00010000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 10), 'unit10-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1001,"question":"You ________ smoke in hospitals.","options":["must","mustn''t","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — smoking is not allowed in hospitals. ''Must'' is for obligation. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1},{"id":1002,"question":"All employees ________ be on time for work.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for strong obligation — employees are required to be on time. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို တာဝန်ဝတ်ရှိမှုတွေမှာ သုံးပါ။","points":1},{"id":1003,"question":"The doctor ________ get here as soon as he can.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for strong obligation — it''s urgent for the doctor to arrive. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို အရေးပေါ်တာဝန်တွေမှာ သုံးပါ။","points":1},{"id":1004,"question":"Bicyclists ________ remember to signal when they turn.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for important rules — cyclists are required to signal. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို အရေးကြီးတဲ့ စည်းကမ်းတွေမှာ သုံးပါ။","points":1},{"id":1005,"question":"Angela, you ________ leave your clothes all over the floor like this.","options":["must","mustn''t","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — Angela should not leave clothes on the floor. ''Must'' is for obligation. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1},{"id":1006,"question":"You ________ watch so much television.","options":["must","mustn''t","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — watching too much TV is not advised. ''Must'' is for obligation. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1},{"id":1007,"question":"Policemen ________ drink on duty.","options":["must","mustn''t","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — policemen are not allowed to drink on duty. ''Must'' is for obligation. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1},{"id":1008,"question":"Children ________ eat chewing gum.","options":["must","mustn''t","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — children are not allowed to eat chewing gum. ''Must'' is for obligation. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1},{"id":1009,"question":"I ________ finish this work before I leave.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for strong personal obligation — finishing work before leaving is necessary. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို တာဝန်ဝတ်ရှိမှုတွေမှာ သုံးပါ။","points":1},{"id":1010,"question":"You ________ patient with me.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for strong personal obligation — being patient is required. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို တာဝန်ဝတ်ရှိမှုတွေမှာ သုံးပါ။","points":1},{"id":1011,"question":"When you drive you ________ wear a seatbelt.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for important safety rules — wearing a seatbelt is required by law. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို အရေးကြီးတဲ့ လုံခြုံရေးစည်းကမ်းတွေမှာ သုံးပါ။","points":1},{"id":1012,"question":"He ________ study harder if he wants to pass the exam.","options":["must","mustn''t","don''t have to"],"answer":"must","explanation":"''Must'' is used for strong obligation — studying harder is necessary to pass. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို တာဝန်ဝတ်ရှိမှုတွေမှာ သုံးပါ။","points":1},{"id":1013,"question":"They ________ use their mobile phones during lessons.","options":["mustn''t","mustn''t be","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — mobile phones are not allowed during lessons. ''Mustn''t be'' would need an adjective. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1},{"id":1014,"question":"________ he make so much noise?","options":["Must","Mustn''t","Don''t have to"],"answer":"Must","explanation":"''Must'' is used in questions to ask about obligation. The speaker is questioning whether the noise is necessary. ''Mustn''t'' is for prohibition. ''Don''t have to'' means it''s not required. ''Must'' ကို မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1015,"question":"I ________ drink any more coffee, otherwise I won''t sleep tonight.","options":["must","mustn''t","don''t have to"],"answer":"mustn''t","explanation":"''Mustn''t'' is used for prohibition — the speaker should not drink more coffee because it will affect sleep. ''Must'' is for obligation. ''Don''t have to'' means it''s not required. ''Mustn''t'' ကို ပိတ်ပင်ချက်တွေမှာ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

