INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00011000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 11), 'unit11-lesson1', 'Have to for Responsibilities', '''Have to'' is used for responsibilities at work and in everyday life. It is conjugated as a regular verb and requires an auxiliary verb in questions and negatives. The structure is Subject + have to + V1.', '{"details":[{"concept":"Work Responsibility","explanation":"''Have to'' is used for work-related responsibilities.","example":"I have to write a letter to John.","burmese":"ကျွန်တော် ဂျွန်ဆီ စာတစ်စောင် ရေးစရာရှိတယ်။"},{"concept":"Schedule Conflict","explanation":"''Have to'' is used when something prevents you from doing something else.","example":"Mike can''t come because he has to work tomorrow.","burmese":"မိုက် အလပ်လပ်စရာရှိလို့ သူ မလာနိုင်ဘူး။"},{"concept":"Education Responsibility","explanation":"''Have to'' is used for educational requirements.","example":"Children have to go to school.","burmese":"ကလေးများ ကျောင်းသွားရမယ်။"},{"concept":"Health Responsibility","explanation":"''Have to'' is used for health-related obligations.","example":"He has to see the doctor.","burmese":"သူ ဆရာဝန်ဆီ သွားရမယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00011001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 11), 'unit11-lesson2', 'Don''t Have to for Not Required', '''Don''t have to'' is used to express that something is not required or not necessary. The structure is Subject + don''t/doesn''t have to + V1.', '{"details":[{"concept":"Not Required (Sunday)","explanation":"''Don''t have to'' means something is not necessary.","example":"I don''t have to work on Sundays so I can do what I want.","burmese":"ကျွန်တော် တနင်္ဂနွေနေ့တွေ အလပ်မရဘူး။ ဒါကြောင့် ငါ ဘာလုပ်ချင်တာလုပ်နိုင်တယ်။"},{"concept":"Not Required (Meeting)","explanation":"''Don''t have to'' means attendance is optional.","example":"She doesn''t have to come to the meeting if she doesn''t want to.","burmese":"အစည်းအဝေး မလာချင်ရင် မလာပါနဲ့။"},{"concept":"Not Required (Driving)","explanation":"''Don''t have to'' means driving is not necessary.","example":"You don''t have to drive today.","burmese":"မင်း ဒီနေ့ မောင်းစရာ မလိုဘူး။"},{"concept":"Not Required (Language)","explanation":"''Don''t have to'' means learning a language is not necessary.","example":"She doesn''t have to learn your language.","burmese":"သူမ မင်းဘာသာစကား သင်စရာ မလိုဘူး။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00011002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 11), 'unit11-lesson3', 'Have to in Past, Present, and Future', '''Have to'' is used in all three tenses. The past form is ''had to''. Questions in the past use ''Did + subject + have to''.', '{"details":[{"concept":"Present Tense","explanation":"Use ''have to'' or ''has to'' for present obligations.","example":"I have to file reports every week.","burmese":"ငါ အပတ်တိုင်း အစီရင်ခံစာ တင်ရမယ်။"},{"concept":"Past Tense","explanation":"Use ''had to'' for past obligations.","example":"She had to pick the children up from school yesterday.","burmese":"သူမ မနေ့က ကလေးတွေကို ကျောင်းကနေ ခေါ်လာခရတယ်။"},{"concept":"Past Question","explanation":"Use ''Did + subject + have to'' for past questions.","example":"Did he have to leave so early?","burmese":"သူ အစောစောထွက်လိုက်ရတာလား။"},{"concept":"Past Tense (Dentist)","explanation":"''Had to'' is used for past obligations like doctor visits.","example":"I had to go to the dentist yesterday.","burmese":"ငါ မနေ့က သွားဆရာဝန်ဆီ သွားရတယ်။"},{"concept":"Past Question (Work)","explanation":"''Did + have to'' is used to ask about past work obligations.","example":"Did they have to do the work over again?","burmese":"သူတို့ အလုပ်ကို ပြန်လုပ်ရတာလား။"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00011000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 11), 'unit11-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1101,"question":"Jack ________ go home early last night.","options":["have to","had to","has to"],"answer":"had to","explanation":"''Last night'' indicates past time, so we use ''had to''. ''Have to'' is for present. ''Has to'' is for third person singular present. ''Last night'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had to'' ကိုသုံးပါ။","points":1},{"id":1102,"question":"I ________ brush my teeth twice a day.","options":["have to","had to","has to"],"answer":"have to","explanation":"''Twice a day'' indicates a present habitual action, so we use ''have to''. ''Had to'' is for past. ''Has to'' is for third person singular. ''Twice a day'' ဆိုတာ ပုံမှန်လုပ်ရတဲ့အတွက် ''have to'' ကိုသုံးပါ။","points":1},{"id":1103,"question":"We ________ buy another ticket yesterday.","options":["have to","had to","has to"],"answer":"had to","explanation":"''Yesterday'' indicates past time, so we use ''had to''. ''Have to'' is for present. ''Has to'' is for third person singular present. ''Yesterday'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had to'' ကိုသုံးပါ။","points":1},{"id":1104,"question":"Susan and Steve ________ pay their rent every Friday.","options":["has to","have to","had to"],"answer":"have to","explanation":"''Every Friday'' indicates a present habitual action, and ''Susan and Steve'' is plural, so we use ''have to''. ''Has to'' is for third person singular. ''Had to'' is for past. ''Every Friday'' ဆိုတာ ပုံမှန်လုပ်ရတဲ့အတွက် ''have to'' ကိုသုံးပါ။","points":1},{"id":1105,"question":"You don''t ________ drive today.","options":["have to","had to","has to"],"answer":"have to","explanation":"''Don''t have to'' means it''s not required. ''Don''t had to'' and ''don''t has to'' are grammatically incorrect. ''Today'' indicates present. ''Don''t have to'' ကို မလိုအပ်တဲ့အခါ သုံးပါ။","points":1},{"id":1106,"question":"The doctor told her that she ________ lose weight.","options":["has to","had to","have to"],"answer":"had to","explanation":"''The doctor told her'' indicates reported speech in the past. In reported speech, ''has to'' changes to ''had to''. ''Has to'' is for present. ''Have to'' is for plural. ''Reported speech မှာ ''has to'' က ''had to'' ပြောင်းပါ။","points":1},{"id":1107,"question":"He ________ see the doctor.","options":["has to","have to","had to"],"answer":"has to","explanation":"''He'' is third person singular, so we use ''has to''. ''Have to'' is for I/you/we/they. ''Had to'' is for past. ''He'' က third person singular ဖြစ်တဲ့အတွက် ''has to'' ကိုသုံးပါ။","points":1},{"id":1108,"question":"She ________ learn your language.","options":["doesn''t have to","doesn''t has to","don''t have to"],"answer":"doesn''t have to","explanation":"''She'' is third person singular, so we use ''doesn''t have to''. ''Doesn''t has to'' is grammatically incorrect. ''Don''t have to'' is for I/you/we/they. ''She'' က third person singular ဖြစ်တဲ့အတွက် ''doesn''t have to'' ကိုသုံးပါ။","points":1},{"id":1109,"question":"Children ________ go to school.","options":["has to","have to","had to"],"answer":"have to","explanation":"''Children'' is plural, so we use ''have to''. ''Has to'' is for third person singular. ''Had to'' is for past. ''Children'' က plural ဖြစ်တဲ့အတွက် ''have to'' ကိုသုံးပါ။","points":1},{"id":1110,"question":"I ________ file reports every week.","options":["have to","had to","has to"],"answer":"have to","explanation":"''Every week'' indicates a present habitual action, so we use ''have to''. ''Had to'' is for past. ''Has to'' is for third person singular. ''Every week'' ဆိုတာ ပုံမှန်လုပ်ရတဲ့အတွက် ''have to'' ကိုသုံးပါ။","points":1},{"id":1111,"question":"Does he ________ go?","options":["has to","have to","had to"],"answer":"have to","explanation":"After ''does'', we use the base form ''have to''. ''Does has to'' is grammatically incorrect. ''Had to'' is for past. ''Does'' ပြီးနောက်မှာ base form ''have to'' ကိုသုံးပါ။","points":1},{"id":1112,"question":"She didn''t ________ attend the presentation.","options":["had to","have to","has to"],"answer":"have to","explanation":"After ''didn''t'', we use the base form ''have to''. ''Didn''t had to'' is grammatically incorrect. ''Has to'' is for third person singular present. ''didn''t'' ပြီးနောက်မှာ base form ''have to'' ကိုသုံးပါ။","points":1},{"id":1113,"question":"I ________ go to the dentist yesterday.","options":["had to","have to","has to"],"answer":"had to","explanation":"''Yesterday'' indicates past time, so we use ''had to''. ''Have to'' is for present. ''Has to'' is for third person singular present. ''Yesterday'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''had to'' ကိုသုံးပါ။","points":1},{"id":1114,"question":"You don''t ________ drive. I can do it.","options":["had to","have to","has to"],"answer":"have to","explanation":"''Don''t have to'' means it''s not required. ''Don''t had to'' and ''Don''t has to'' are grammatically incorrect. This is a present situation. ''Don''t have to'' ကို မလိုအပ်တဲ့အခါ သုံးပါ။","points":1},{"id":1115,"question":"Did they ________ do the work over again?","options":["had to","have to","has to"],"answer":"have to","explanation":"After ''did'', we use the base form ''have to''. ''Did had to'' is grammatically incorrect. ''Has to'' is for third person singular present. ''Did'' ပြီးနောက်မှာ base form ''have to'' ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

